  {
    "id": "P0046",
    "report": "A",
    "text": "Locations: `crate/src/sync/base_cache.rs:2316`, `crate/src/sync/base_cache.rs:2340`; corresponding functions at `crate/src/future/base_cache.rs:2513` and `:2554`\n\n"
